    <script src="/static/js/erp_jalali.js" defer></script>
    <script src="/static/js/erp_money.js" defer></script>
    <script src="/static/js/erp_table.js" defer></script>
    <script src="/static/js/erp_context.js" defer></script>
    <style>
         :root {
            --erp-canvas: #f8fafc;
            --erp-surface: #ffffff;
            --erp-surface-subtle: #f1f5f9;
            --erp-border: #e2e8f0;
            --erp-border-strong: #cbd5e1;
            --erp-text: #0f172a;
            --erp-text-muted: #64748b;
            --erp-primary: #1d4ed8;
            --erp-primary-hover: #1e40af;
            --erp-sidebar: #0f172a;
            --erp-sidebar-border: #1e293b;
            --erp-radius-control: .5rem;
            --erp-radius-card: .75rem;
        }

        @font-face {
            font-family: "Vazirmatn";
            src: url("/static/fonts/vazirmatn/Vazirmatn-Regular.woff2") format("woff2");
            font-style: normal;
            font-weight: 400;
            font-display: swap;
        }

        @font-face {
            font-family: "Vazirmatn";
            src: url("/static/fonts/vazirmatn/Vazirmatn-Medium.woff2") format("woff2");
            font-style: normal;
            font-weight: 500;
            font-display: swap;
        }

        @font-face {
            font-family: "Vazirmatn";
            src: url("/static/fonts/vazirmatn/Vazirmatn-SemiBold.woff2") format("woff2");
            font-style: normal;
            font-weight: 600;
            font-display: swap;
        }

        @font-face {
            font-family: "Vazirmatn";
            src: url("/static/fonts/vazirmatn/Vazirmatn-Bold.woff2") format("woff2");
            font-style: normal;
            font-weight: 700;
            font-display: swap;
        }

        body {
            font-family: "Vazirmatn", Tahoma, "Segoe UI", Arial, sans-serif;
            font-feature-settings: "ss01";
            overflow-x: hidden;
            font-size: .875rem;
            line-height: 1.5;
        }

         :where(a,
        button,
        input,
        select,
        textarea,
        summary):focus-visible {
            outline: 2px solid rgb(59 130 246);
            outline-offset: 2px;
        }

        main input:not([type="hidden"]):not([type="checkbox"]):not([type="radio"]):not([type="submit"]),
        main select,
        main textarea {
            display: block;
            width: 100%;
            min-height: 2.75rem;
            border: 1px solid rgb(203 213 225);
            border-radius: .625rem;
            background: white;
            padding: .625rem .75rem;
            color: rgb(15 23 42);
        }

        main textarea {
            min-height: 7rem;
        }

        main input[type="file"],
        main select[multiple] {
            height: auto;
        }

        main input:not([type="hidden"]):not([type="checkbox"]):not([type="radio"]):not([type="submit"]):focus,
        main select:focus,
        main textarea:focus {
            border-color: rgb(37 99 235);
            outline: none;
            box-shadow: 0 0 0 3px rgb(219 234 254);
        }

        main input:disabled,
        main select:disabled,
        main textarea:disabled {
            background: rgb(248 250 252);
            color: rgb(100 116 139);
        }

        main input[type="email"],
        main input[type="url"],
        main input[type="password"],
        main input[type="number"],
        main input[type="date"],
        main input[type="datetime-local"],
        main input[type="time"],
        main input[name="username"],
        main input[name="code"],
        main input[name$="-code"],
        main input[name$="_code"],
        main input[name$="number"],
        main input[name*="uuid"],
        main input[name$="_id"] {
            direction: ltr;
            text-align: left;
            unicode-bidi: plaintext;
        }

        .erp-surface {
            border: 1px solid var(--erp-border);
            background: var(--erp-surface);
            box-shadow: 0 1px 2px rgb(15 23 42 / .035);
        }

        .erp-surface--raised {
            box-shadow: 0 4px 6px -1px rgb(15 23 42 / .06), 0 2px 4px -2px rgb(15 23 42 / .04);
        }

        .erp-btn {
            display: inline-flex;
            min-height: 2.5rem;
            align-items: center;
            justify-content: center;
            gap: .5rem;
            border: 1px solid transparent;
            border-radius: var(--erp-radius-control);
            padding: .5rem 1rem;
            font-size: .8125rem;
            font-weight: 600;
            line-height: 1.25rem;
            transition: border-color .15s ease, background-color .15s ease, color .15s ease, box-shadow .15s ease;
        }

        .erp-btn--primary {
            background: var(--erp-primary);
            color: white;
            box-shadow: 0 1px 2px rgb(15 23 42 / .08);
        }

        .erp-btn--primary:hover {
            background: var(--erp-primary-hover);
        }

        .erp-btn--secondary {
            border-color: var(--erp-border-strong);
            background: white;
            color: rgb(51 65 85);
        }

        .erp-btn--secondary:hover {
            border-color: rgb(148 163 184);
            background: var(--erp-surface-subtle);
            color: var(--erp-text);
        }

        .erp-btn--compact {
            min-height: 2rem;
            padding: .25rem .5rem;
            font-size: .6875rem;
            line-height: 1rem;
        }

        .erp-btn--active,
        .erp-btn--active:hover {
            border-color: var(--erp-primary);
            background: var(--erp-primary);
            color: white;
            box-shadow: 0 1px 2px rgb(15 23 42 / .08);
        }

        .erp-btn--danger {
            border-color: rgb(254 202 202);
            background: white;
            color: rgb(185 28 28);
        }

        .erp-btn--danger:hover {
            background: rgb(254 242 242);
        }

        .erp-badge {
            display: inline-flex;
            min-height: 1.5rem;
            align-items: center;
            gap: .35rem;
            border: 1px solid;
            border-radius: .375rem;
            padding: .15rem .5rem;
            font-size: .7rem;
            font-weight: 600;
            line-height: 1rem;
            white-space: nowrap;
        }

        .erp-badge::before {
            width: .35rem;
            height: .35rem;
            flex: 0 0 .35rem;
            border-radius: 9999px;
            background: currentColor;
            content: "";
        }

        .erp-badge--neutral {
            border-color: rgb(203 213 225);
            background: rgb(241 245 249);
            color: rgb(71 85 105);
        }

        .erp-badge--info {
            border-color: rgb(191 219 254);
            background: rgb(239 246 255);
            color: rgb(29 78 216);
        }

        .erp-badge--success {
            border-color: rgb(187 247 208);
            background: rgb(240 253 244);
            color: rgb(21 128 61);
        }

        .erp-badge--warning {
            border-color: rgb(253 230 138);
            background: rgb(255 251 235);
            color: rgb(180 83 9);
        }

        .erp-badge--danger {
            border-color: rgb(254 202 202);
            background: rgb(254 242 242);
            color: rgb(185 28 28);
        }

        .erp-panel-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 1rem;
            border-bottom: 1px solid var(--erp-border);
            padding: .875rem 1rem;
        }

        .erp-table-wrap {
            width: 100%;
            overflow-x: auto;
            overscroll-behavior-inline: contain;
        }

        .erp-scrollbar {
            scrollbar-width: thin;
            scrollbar-color: rgb(71 85 105) transparent;
        }

        .erp-skip-link {
            position: fixed;
            top: .5rem;
            right: .5rem;
            z-index: 100;
            transform: translateY(-150%);
            border-radius: .5rem;
            background: rgb(37 99 235);
            padding: .65rem 1rem;
            color: white;
            font-size: .75rem;
            font-weight: 700;
            transition: transform .15s ease;
        }

        .erp-skip-link:focus {
            transform: translateY(0);
        }

        .erp-nav {
            display: flex;
            flex-direction: column;
            gap: .25rem;
        }

        .erp-nav-link {
            position: relative;
            display: flex;
            min-height: 2.5rem;
            align-items: center;
            gap: .7rem;
            border-radius: .55rem;
            padding: .55rem .7rem;
            color: rgb(203 213 225);
            font-size: .78rem;
            font-weight: 500;
            transition: color .15s ease, background-color .15s ease, transform .15s ease;
        }

        .erp-nav-link:hover {
            background: rgb(255 255 255 / .08);
            color: white;
        }

        .erp-nav-link.is-active {
            background: rgb(29 78 216);
            color: white;
            font-weight: 600;
            box-shadow: 0 6px 16px rgb(2 6 23 / .22);
        }

        .erp-nav-link.is-active::after {
            position: absolute;
            inset-block: .55rem;
            right: -.75rem;
            width: 3px;
            border-radius: 99px 0 0 99px;
            background: rgb(147 197 253);
            content: "";
        }

        .erp-nav-link.is-unavailable {
            cursor: default;
            color: rgb(100 116 139);
        }

        .erp-nav-link>svg {
            width: 1.1rem;
            height: 1.1rem;
            flex: 0 0 1.1rem;
            fill: none;
            stroke: currentColor;
            stroke-linecap: round;
            stroke-linejoin: round;
            stroke-width: 1.7;
        }

        .erp-nav-group {
            margin-top: .35rem;
            border-top: 1px solid rgb(255 255 255 / .055);
            padding-top: .35rem;
        }

        .erp-nav-group>summary {
            display: flex;
            min-height: 1.9rem;
            cursor: pointer;
            list-style: none;
            align-items: center;
            justify-content: space-between;
            padding: .25rem .7rem;
            color: rgb(148 163 184);
            font-size: .64rem;
            font-weight: 600;
            letter-spacing: .025em;
        }

        .erp-nav-group>summary::-webkit-details-marker {
            display: none;
        }

        .erp-nav-group>summary svg {
            width: .9rem;
            height: .9rem;
            fill: none;
            stroke: currentColor;
            stroke-width: 1.8;
            transition: transform .15s ease;
        }

        .erp-nav-group:not([open])>summary svg {
            transform: rotate(90deg);
        }

        .erp-nav-group>summary:hover {
            color: rgb(226 232 240);
        }

        .erp-nav-group__items {
            display: grid;
            gap: .1rem;
            border-right: 1px solid rgb(148 163 184 / .14);
            margin-right: .7rem;
            padding-right: .35rem;
        }

        .erp-page-header {
            display: flex;
            align-items: flex-end;
            justify-content: space-between;
            gap: 1rem;
            min-height: 4.5rem;
        }

        .erp-page-header__copy {
            min-width: 0;
        }

        .erp-page-header__action:focus-visible {
            outline-color: rgb(30 64 175);
            outline-offset: 3px;
        }

        .erp-required {
            margin-right: .2rem;
            color: rgb(220 38 38);
            font-weight: 700;
        }

        .erp-form-field--invalid label {
            color: rgb(153 27 27);
        }

        .erp-form-field--invalid :where(input,
        select,
        textarea) {
            border-color: rgb(248 113 113) !important;
            background-color: rgb(254 242 242 / .5);
        }

        .erp-field-help {
            line-height: 1.6;
        }

        .erp-field-error {
            display: flex;
            align-items: center;
            gap: .3rem;
            font-size: .75rem;
            font-weight: 500;
        }

        .erp-field-error::before {
            display: grid;
            width: 1rem;
            height: 1rem;
            place-items: center;
            border-radius: 50%;
            background: rgb(254 226 226);
            content: "!";
            font-size: .65rem;
            font-weight: 700;
        }

        .erp-message {
            display: flex;
            align-items: flex-start;
            gap: .65rem;
            line-height: 1.7;
        }

        .erp-message__icon {
            display: grid;
            width: 1.35rem;
            height: 1.35rem;
            flex: 0 0 1.35rem;
            place-items: center;
            border-radius: 50%;
            color: white;
            font-size: .7rem;
            font-weight: 800;
        }

        .erp-message--error .erp-message__icon {
            background: rgb(220 38 38);
        }

        .erp-message--warning .erp-message__icon {
            background: rgb(217 119 6);
        }

        .erp-message--success .erp-message__icon {
            background: rgb(5 150 105);
        }

        .erp-message--info .erp-message__icon {
            background: rgb(37 99 235);
        }

        main form.erp-surface>section+section {
            border-top: 1px solid rgb(241 245 249);
            padding-top: 1.25rem;
        }

        main form.erp-surface>section>h2,
        main .erp-surface>h2 {
            color: rgb(15 23 42);
            font-weight: 700;
            letter-spacing: -.01em;
        }

        main form.erp-surface> :last-child:is(.border-t) {
            margin-top: 1.25rem;
            background: rgb(248 250 252 / .7);
            margin-inline: -1.25rem;
            margin-bottom: -1.25rem;
            padding: 1rem 1.25rem;
        }

        main .overflow-x-auto {
            scrollbar-width: thin;
            scrollbar-color: rgb(148 163 184) rgb(241 245 249);
        }

        main table {
            border-collapse: separate;
            border-spacing: 0;
        }

        main table thead th {
            position: relative;
            background: rgb(248 250 252);
            color: rgb(71 85 105);
            font-size: .72rem;
            font-weight: 700;
            letter-spacing: .01em;
            line-height: 1.45;
            white-space: nowrap;
        }

        main table tbody tr {
            transition: background-color .12s ease, box-shadow .12s ease;
        }

        main table tbody tr:hover {
            background: rgb(239 246 255 / .68);
            box-shadow: inset -3px 0 0 rgb(59 130 246);
        }

        main table tbody td {
            color: rgb(51 65 85);
            vertical-align: middle;
            font-size: .8125rem;
        }

        main table :where(td,
        th)[dir="ltr"],
        main table :where(.tabular-nums) {
            text-align: left;
            font-feature-settings: "ss01", "tnum";
            font-variant-numeric: tabular-nums;
        }

         :where(code,
        kbd,
        samp,
        [dir="ltr"]) {
            direction: ltr;
            unicode-bidi: isolate;
        }

        main :where(button,
        a)[class*="bg-blue-600"] {
            transition: background-color .15s ease, box-shadow .15s ease;
        }

        main :where(button,
        input,
        select,
        textarea):disabled {
            cursor: not-allowed;
            opacity: .68;
        }

        main [aria-busy="true"] {
            cursor: progress;
            opacity: .72;
        }

        main .erp-surface> :where(.p-12,
        .py-16):where(.text-center) {
            min-height: 11rem;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            background: linear-gradient(180deg, white, rgb(248 250 252 / .75));
            color: rgb(100 116 139);
        }

        @media (max-width: 639px) {
            .erp-page-header {
                align-items: stretch;
                flex-direction: column;
            }
            .erp-page-header__action {
                width: 100%;
            }
            main form.erp-surface> :last-child:is(.border-t) {
                flex-direction: column-reverse;
                align-items: stretch;
            }
            main form.erp-surface> :last-child:is(.border-t) :where(a,
            button) {
                width: 100%;
                text-align: center;
            }
        }

        .erp-mobile-nav>summary::-webkit-details-marker {
            display: none;
        }

        .erp-mobile-nav__backdrop {
            display: none;
            position: fixed;
            inset: 3.75rem 0 0;
            z-index: 40;
            cursor: default;
            background: rgb(15 23 42 / .55);
        }

        .erp-mobile-nav__panel {
            display: none;
            position: fixed;
            top: 3.75rem;
            right: 0;
            bottom: 0;
            z-index: 50;
            width: min(20rem, 88vw);
            overflow-y: auto;
            border-left: 1px solid var(--erp-sidebar-border);
            background: var(--erp-sidebar);
            padding: 1rem .75rem;
            box-shadow: -20px 0 30px rgb(15 23 42 / .18);
        }

        .erp-mobile-nav[open] :where(.erp-mobile-nav__backdrop,
        .erp-mobile-nav__panel) {
            display: block;
        }

        @media (prefers-reduced-motion: reduce) {
            *,
            *::before,
            *::after {
                scroll-behavior: auto !important;
                transition-duration: .01ms !important;
            }
        }
    </style>

</head>

<body class="min-h-screen bg-slate-50 text-slate-900 antialiased">
    <a class="erp-skip-link" href="#main-content">رفتن به محتوای اصلی</a> 
        <main id="main-content" tabindex="-1" class="mx-auto min-w-0 min-h-screen max-w-7xl px-4 py-10 sm:px-6 lg:px-8">


<nav class="mb-3 flex items-center gap-2 text-[11px] text-slate-400" aria-label="مسیر صفحه">
    <a class="transition hover:text-blue-700" href="/">خانه</a>
    <svg class="h-3 w-3" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m15 18-6-6 6-6"/></svg>

    <span class="truncate text-slate-600">تراز و صورت‌های مالی</span>
</nav>
<header class="erp-page-header" aria-labelledby="erp-page-title">
    <div class="erp-page-header__copy">

            <p class="text-xs font-semibold text-blue-600">حسابداری</p>

        <h1 id="erp-page-title" class="mt-1 text-2xl font-bold tracking-tight text-slate-950">تراز و صورت‌های مالی</h1>

            <p class="mt-1 text-sm text-slate-500">فقط بر پایه ردیف‌های قطعی و تصاویر نگهداری‌شده دفترکل</p>

    </div>

</header>

<nav class="mt-5 flex flex-wrap gap-2" aria-label="بخش‌های حسابداری">
    <a class="erp-btn erp-btn--secondary" href="/accounting/">نمای کلی</a>
    <a class="erp-btn erp-btn--secondary" href="/accounting/accounts/">کدینگ حساب‌ها</a>
    <a class="erp-btn erp-btn--secondary" href="/accounting/periods/">سال و دوره مالی</a>
    <a class="erp-btn erp-btn--secondary" href="/accounting/journals/">اسناد حسابداری</a>
    <a class="erp-btn erp-btn--secondary" href="/accounting/openings/">مانده افتتاحیه</a>
    <a class="erp-btn erp-btn--secondary" href="/accounting/reconciliations/">تطبیق‌ها</a>

</nav>

<form class="erp-surface mt-5 rounded-xl p-5" method="get">


    <div class="grid gap-4 sm:grid-cols-3">
<div class="erp-form-field">
    <label class="mb-1.5 block text-sm font-medium text-slate-700" for="id_kind">
        نوع گزارش<span class="erp-required" aria-hidden="true" title="الزامی">*</span><span class="sr-only"> (الزامی)</span>
    </label>
    <select name="kind" class="block w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-slate-900 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100" id="id_kind">
  <option value="trial_balance">تراز آزمایشی</option>

  <option value="balance_sheet" selected>ترازنامه</option>

  <option value="profit_loss">صورت سود و زیان</option>

</select>


</div>

<div class="erp-form-field">
    <label class="mb-1.5 block text-sm font-medium text-slate-700" for="id_starts_on">
        شروع بازه
    </label>
    <input type="text" name="starts_on" value="1405/07/09" data-jalali-date="date" data-input-mask="####/##/##" inputmode="numeric" autocomplete="off" class="block w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-slate-900 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100" id="id_starts_on">


</div>

<div class="erp-form-field">
    <label class="mb-1.5 block text-sm font-medium text-slate-700" for="id_ends_on">
        پایان / تاریخ برش<span class="erp-required" aria-hidden="true" title="الزامی">*</span><span class="sr-only"> (الزامی)</span>
    </label>
    <input type="text" name="ends_on" value="1405/07/30" data-jalali-date="date" data-input-mask="####/##/##" inputmode="numeric" autocomplete="off" class="block w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-slate-900 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100" required id="id_ends_on">


</div>
</div>
    <button class="erp-btn erp-btn--secondary mt-4" type="submit">پیش‌نمایش خواندنی</button>
</form>

<section class="erp-surface mt-5 overflow-hidden rounded-xl">
    <div class="erp-panel-header"><div><h2 class="font-semibold text-slate-900">پیش‌نمایش balance_sheet</h2><p class="text-xs text-slate-500"> ردیف قطعی · IRR</p></div></div>
    <div class="erp-table-wrap"><table class="w-full min-w-[980px] text-right text-sm"><thead><tr><th class="px-4 py-3">حساب</th><th class="px-4 py-3">نوع</th><th class="px-4 py-3">افتتاح بدهکار</th><th class="px-4 py-3">افتتاح بستانکار</th><th class="px-4 py-3">گردش بدهکار</th><th class="px-4 py-3">گردش بستانکار</th><th class="px-4 py-3">مانده / مبلغ</th></tr></thead><tbody class="divide-y divide-slate-100"><tr><td class="px-4 py-3"><span dir="ltr"></span> — </td><td class="px-4 py-3">equity</td><td class="px-4 py-3 tabular-nums" dir="ltr"></td><td class="px-4 py-3 tabular-nums" dir="ltr"></td><td class="px-4 py-3 tabular-nums" dir="ltr"></td><td class="px-4 py-3 tabular-nums" dir="ltr"></td><td class="px-4 py-3 font-semibold tabular-nums" dir="ltr"></td></tr></tbody></table></div>
</section>

<section class="erp-surface mt-5 overflow-hidden rounded-xl"><div class="erp-panel-header"><div><h2 class="font-semibold text-slate-900">نسخه‌های نگهداری‌شده</h2><p class="text-xs text-slate-500">نتیجه و شواهد پس از ایجاد قابل ویرایش نیستند.</p></div></div><div class="erp-table-wrap"><table class="w-full min-w-[760px] text-right text-sm"><thead><tr><th class="px-4 py-3">نوع</th><th class="px-4 py-3">بازه / برش</th><th class="px-4 py-3">ایجادکننده</th><th class="px-4 py-3">ردیف منبع</th><th class="px-4 py-3">زمان</th></tr></thead><tbody class="divide-y divide-slate-100"><tr><td colspan="5" class="px-4 py-8 text-center text-slate-500">گزارش نگهداری‌شده‌ای وجود ندارد.</td></tr></tbody></table></div></section>

        </main>

    <script>
        (() => {
            document.querySelectorAll("[data-mobile-nav]").forEach((drawer) => {
