 (() => {
 const persianLabels = new Map([
 ["Draft", "پیش‌نویس"],
 ["Active", "فعال"],
 ["Approved", "تأییدشده"],
 ["Completed", "تکمیل‌شده"],
 ["Labor", "نیروی انسانی"],
