 ["Recorded", "ثبت‌شده"],
 ["Posted", "ثبت‌شده"],
 ["Void", "باطل‌شده"],
 ]);
 const skippedTags = new Set(["SCRIPT", "STYLE", "TEXTAREA", "CODE", "PRE"]);
 const localize = () => {
 const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
 const nodes = [];
 while (walker.nextNode()) {
 if (!skippedTags.has(walker.currentNode.parentElement?.tagName)) nodes.push(walker.currentNode);
 }
 nodes.forEach((node) => {
 const trimmed = node.nodeValue.trim();
 if (persianLabels.has(trimmed)) node.nodeValue = node.nodeValue.replace(trimmed, persianLabels.get(trimmed));
 });
 };
 if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", localize, {
 once: true
 });
 else localize();
 })();
 </script>

