 drawer.addEventListener("toggle", () => summary.setAttribute("aria-expanded", String(drawer.open)));
 drawer.querySelectorAll("[data-mobile-nav-close], a").forEach((item) => item.addEventListener("click", close));
 document.addEventListener("keydown", (event) => { if (event.key === "Escape" && drawer.open) close(); });
 });
 })();
 (() => {
 const persianLabels = new Map([
 ["Draft", "پیش‌نویس"],
 ["Active", "فعال"],
 ["Approved", "تأییدشده"],
 ["Completed", "تکمیل‌شده"],
 ["Labor", "نیروی انسانی"],
 ["Equipment", "تجهیزات"],
 ["Material", "مصالح"],
 ["Other", "سایر"],
