 (() => {
 document.querySelectorAll("[data-mobile-nav]").forEach((drawer) => {
 const summary = drawer.querySelector("summary");
 const close = () => { drawer.open = false; summary.setAttribute("aria-expanded", "false"); };
 drawer.addEventListener("toggle", () => summary.setAttribute("aria-expanded", String(drawer.open)));
 drawer.querySelectorAll("[data-mobile-nav-close], a").forEach((item) => item.addEventListener("click", close));
 document.addEventListener("keydown", (event) => { if (event.key === "Escape" && drawer.open) close(); });
 });
 })();
 (() => {
 const persianLabels = new Map([
 ["Draft", "پیش‌نویس"],
 ["Active", "فعال"],
 ["Approved", "تأییدشده"],
 ["Completed", "تکمیل‌شده"],
 ["Labor", "نیروی انسانی"],
 ["Equipment", "تجهیزات"],
 ["Material", "مصالح"],
 ["Other", "سایر"],
 ["Planning", "در حال برنامه‌ریزی"],
 ["On hold", "متوقف‌شده"],
 ["Cancelled", "لغوشده"],
 ["Submitted", "ارسال‌شده"],
 ["Terminated", "خاتمه‌یافته"],
 ["Recorded", "ثبت‌شده"],
 ["Posted", "ثبت‌شده"],
 ["Void", "باطل‌شده"],
 ]);
 const skippedTags = new Set(["SCRIPT", "STYLE", "TEXTAREA", "CODE", "PRE"]);
 const localize = () => {
 const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
 const nodes = [];
 while (walker.nextNode()) {
 if (!skippedTags.has(walker.currentNode.parentElement?.tagName)) nodes.push(walker.currentNode);
 }
 nodes.forEach((node) => {
 const trimmed = node.nodeValue.trim();
 if (persianLabels.has(trimmed)) node.nodeValue = node.nodeValue.replace(trimmed, persianLabels.get(trimmed));
 });
 };
 if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", localize, {
 once: true
 });
 else localize();
 })();
 </script>

