    <div class="erp-table-wrap"><table class="w-full min-w-[980px] text-right text-sm"><thead><tr><th class="px-4 py-3">حساب</th><th class="px-4 py-3">نوع</th><th class="px-4 py-3">افتتاح بدهکار</th><th class="px-4 py-3">افتتاح بستانکار</th><th class="px-4 py-3">گردش بدهکار</th><th class="px-4 py-3">گردش بستانکار</th><th class="px-4 py-3">مانده / مبلغ</th></tr></thead><tbody class="divide-y divide-slate-100"><tr><td class="px-4 py-3"><span dir="ltr"></span> — </td><td class="px-4 py-3">expense</td><td class="px-4 py-3 tabular-nums" dir="ltr"></td><td class="px-4 py-3 tabular-nums" dir="ltr"></td><td class="px-4 py-3 tabular-nums" dir="ltr"></td><td class="px-4 py-3 tabular-nums" dir="ltr"></td><td class="px-4 py-3 font-semibold tabular-nums" dir="ltr"></td></tr></tbody></table></div>
</section>

<section class="erp-surface mt-5 overflow-hidden rounded-xl"><div class="erp-panel-header"><div><h2 class="font-semibold text-slate-900">نسخه‌های نگهداری‌شده</h2><p class="text-xs text-slate-500">نتیجه و شواهد پس از ایجاد قابل ویرایش نیستند.</p></div></div><div class="erp-table-wrap"><table class="w-full min-w-[760px] text-right text-sm"><thead><tr><th class="px-4 py-3">نوع</th><th class="px-4 py-3">بازه / برش</th><th class="px-4 py-3">ایجادکننده</th><th class="px-4 py-3">ردیف منبع</th><th class="px-4 py-3">زمان</th></tr></thead><tbody class="divide-y divide-slate-100"><tr><td colspan="5" class="px-4 py-8 text-center text-slate-500">گزارش نگهداری‌شده‌ای وجود ندارد.</td></tr></tbody></table></div></section>

        </main>

    <script>
        (() => {
            document.querySelectorAll("[data-mobile-nav]").forEach((drawer) => {
                const summary = drawer.querySelector("summary");
                const close = () => { drawer.open = false; summary.setAttribute("aria-expanded", "false"); };
                drawer.addEventListener("toggle", () => summary.setAttribute("aria-expanded", String(drawer.open)));
                drawer.querySelectorAll("[data-mobile-nav-close], a").forEach((item) => item.addEventListener("click", close));
                document.addEventListener("keydown", (event) => { if (event.key === "Escape" && drawer.open) close(); });
            });
        })();
        (() => {
            const persianLabels = new Map([
                ["Draft", "پیش‌نویس"],
                ["Active", "فعال"],
                ["Approved", "تأییدشده"],
                ["Completed", "تکمیل‌شده"],
                ["Labor", "نیروی انسانی"],
                ["Equipment", "تجهیزات"],
                ["Material", "مصالح"],
                ["Other", "سایر"],
                ["Planning", "در حال برنامه‌ریزی"],
                ["On hold", "متوقف‌شده"],
                ["Cancelled", "لغوشده"],
                ["Submitted", "ارسال‌شده"],
                ["Terminated", "خاتمه‌یافته"],
                ["Recorded", "ثبت‌شده"],
                ["Posted", "ثبت‌شده"],
                ["Void", "باطل‌شده"],
            ]);
            const skippedTags = new Set(["SCRIPT", "STYLE", "TEXTAREA", "CODE", "PRE"]);
            const localize = () => {
                const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
                const nodes = [];
                while (walker.nextNode()) {
                    if (!skippedTags.has(walker.currentNode.parentElement?.tagName)) nodes.push(walker.currentNode);
                }
                nodes.forEach((node) => {
                    const trimmed = node.nodeValue.trim();
                    if (persianLabels.has(trimmed)) node.nodeValue = node.nodeValue.replace(trimmed, persianLabels.get(trimmed));
                });
            };
            if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", localize, {
                once: true
            });
            else localize();
        })();
    </script>

</body>

</html>
